310: // Index 0 = Red level, 1 = Amber level, 2 = Orange level
311: const CHOICE_THRESHOLDS: Record<string, [number, number, number]> = {
312:   Cognitive: [1.8, 2.2, 2.8],
313:   Emotional: [2, 2.5, 3],
314:   Moral: [2, 2.5, 3],
315:   Intrapersonal: [2, 2.5, 3],
316:   Spiritual: [2, 2.5, 3],
