503: function stageColor(stage: string): (text: string) => string {
504:   const colors: Record<string, (text: string) => string> = {
505:     Infrared: chalk.hex('#8B0000'),
506:     Magenta: chalk.hex('#BA55D3'),
507:     Red: chalk.hex('#FF0000'),
508:     Amber: chalk.hex('#FF8C00'),
509:     Orange: chalk.hex('#FFA500'),
510:     Green: chalk.hex('#00C853'),
511:     Turquoise: chalk.hex('#00CED1'),
512:     White: chalk.hex('#FFFFFF'),
513:   };
514:   return colors[stage] ?? chalk.dim;
515: }
