export async function queryLLMWithTools(
  systemPrompt: string,
  messages: readonly AgentMessage[],
  tools?: readonly any[],
): Promise<LLMToolResponse> {
  const baseUrl = getEnvVal('VITE_LLM_BASE_URL');
  const apiKey = getEnvVal('VITE_LLM_API_KEY');
  const model = getEnvVal('VITE_LLM_MODEL');

  if (!baseUrl || !apiKey || apiKey === 'sk-placeholder' || !model) {
    return { content: '{"error": "LLM unavailable"}' };
  }

  // Map AgentMessage to OpenAI API format
  const mappedMessages = [
    { role: 'system', content: systemPrompt },
    ...messages.map(msg => {
      const result: any = {
        role: msg.role,
        content: msg.content,
      };
      if (msg.toolCalls) {
        result.tool_calls = msg.toolCalls.map(tc => ({
          id: tc.id,
          type: tc.type,
          function: {
            name: tc.function.name,
            arguments: tc.function.arguments,
          },
        }));
      }
      if (msg.toolCallId) {
        result.tool_call_id = msg.toolCallId;
      }
      if (msg.name) {
        result.name = msg.name;
      }
      return result;
    }),
  ];

  try {
    const body: any = {
      model,
      messages: mappedMessages,
      temperature: 0.7,
    };
    if (tools && tools.length > 0) {
      body.tools = tools;
    }

    const res = await fetchWithTimeout(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      return { content: `{"error": "fetch error: ${res.status}"}` };
    }

    const data = (await res.json()) as {
      choices: {
        message: {
          content: string | null;
          tool_calls?: {
            id: string;
            type: 'function';
            function: {
              name: string;
              arguments: string;
            };
          }[];
        };
      }[];
    };

    const choice = data.choices[0]?.message;
    if (!choice) {
      return { content: null };
    }

    return {
      content: choice.content,
      toolCalls: choice.tool_calls?.map(tc => ({
        id: tc.id,
        type: tc.type,
        function: {
          name: tc.function.name,
          arguments: tc.function.arguments,
        },
      })),
    };
  } catch (err: any) {
    return { content: `{"error": "exception: ${err.message || err}"}` };
  }
}

